		// Token: 0x06004842 RID: 18498
		void BeginRun();

		/// <summary>
		/// Called when a player readies or un-readies.
		/// </summary>
		// Token: 0x06004843 RID: 18499
		void PlayerReadyChanged(ulong playerId);

		/// <summary>
		/// Called when the local player has been disconnected from the lobby.
		/// <param name="info">Information about why we were disconnected.</param>
		/// </summary>
		// Token: 0x06004844 RID: 18500
		void LocalPlayerDisconnected(NetErrorInfo info);
	}
}
